+    flex-direction: column;
+    justify-content: space-between;
+    padding: 20px;
+    align-items: center;
+    background-color: #16191B;
+
+    @media (max-width: 930px) {
+      width: calc(100vw - 40px);
+      overflow: hidden;
+    }
+    .divTitle {
+      margin-top: 40px;
+      display: flex;
+      flex-direction: column;
+      align-items: center;
+      justify-content: center;
+
+      h1 {
+        margin: 0;
+        color: #04F000;
+        font-family: 'Aguafina Script', cursive;
+        font-size: 4rem;
+        font-weight: 400;
+      }
+      h3 {
+        margin: 0;
+        color: #F2F2F2;
+        font-family: 'Poppins', sans-serif;
+        font-size: 2rem;
+        font-weight: 300;
+      }
+      p {
+        color: #F2F2F2;
+        font-size: 12px;
+        font-weight: 300;
+        margin: 0;
+        text-align: center;
+        display: flex;
+      }
+    }
+    p {
+      text-align: center;
+      display: flex;
+      color: #F2F2F2;
+    }
+    footer {
+      display: flex;
+      flex-direction: column;
+      align-items: center;
+      justify-content: center;
+
+      .assignDeveloper {
+        margin: 0%;
+        color: #F2F2F2;
+        font-size: 10px;
+        font-weight: 300;
+      }
+    }
+    
+    .centerCard {
+      display: flex;
+      flex-direction: column;
+      align-items: center;
+      justify-content: center;
+      gap: 10px;
+      width: -webkit-fill-available;
+
+      select {
+        width: 84%;
+        border-radius: 5px;
+        height: 40px;
+        margin-bottom: 10px;
+      }
+      input {
+        width: 80%;
+        height: 40px;
+        border: 2px solid #F2F2F2;
+        border-radius: 5px;
+        padding: 0 10px;
+        /* background-color: #16191B; */
+        color: #16191B;
+        font-size: 16px;
+        font-weight: 300;
+        outline: none;
+        margin-bottom: 35px;
+        transition: all 0.3s ease;
+        &::placeholder {
+          color: #F2F2F2;
+          font-size: 16px;
+          font-weight: 300;
+        }
+        &:focus {
+          border-color: #04F000;
+        }
+      }
+      label {
+        color: #F2F2F2;
+        font-size: 16px;
+        font-weight: 300;
+        display: flex;
+        justify-content: flex-start;
+        width: 80%;
+      }
+      button {
+        width: 80%;
+        height: 40px;
+        border-radius: 5px;
+        padding: 0 10px;
+        background-color: #012B00;
+        color: #FFFFFF;
+        font-family: 'Poppins', sans-serif;
+        font-size: 16px;
+        font-weight: 600;
+        outline: none;
+        transition: all 0.3s ease;
+      }
+      button:hover {
+        background-color: #F2F2F2;
+        color: #16191B;
+        cursor: pointer;
+      }
+      button:active {
+        background-color: #04F000;
+        color: #16191B;
+        cursor: pointer;
+        opacity: 0.5;
+      }
+      button:disabled {
+        background-color: #F2F2F2;
+        color: #16191B;
+        cursor: not-allowed;
+        opacity: 0.5;
+      }
+      button:focus {
+        outline: none;
+      }
+      button:focus-visible {
+        outline: 1px solid #F2F2F2;
+      }
+      .registerButton {
+        background-color: #F2F2F2;
+        color: #012B00;
+        font-family: 'Poppins', sans-serif;
+        font-size: 16px;
+        font-weight: 600;
+        outline: none;
+        transition: all 0.3s ease;
+        margin-top: 10px;
+
+      }
+      .registerButton:hover {
+        background-color: #012B00;
+        text-decoration: underline;
+        color: #F2F2F2;
+        cursor: pointer;
+        transition: all 0.4s ease-in-out;
+      }
+      .registerLink {
+        color: #04F000;
+        font-weight: 600;
+      }
+      .tagRegister {
+        margin-top: 10px;
+        font-size: 12px;
+        font-weight: 300;
+        gap: 3px;
+      }
+      .registerLink {
+        color: #04F000;
+        font-weight: 600;
+        text-decoration: none;
+      }
+      .registerLink:hover {
+        text-decoration: underline;
+      }
+    }
+  }
+}

